import {
  $,
  component$,
  useOnDocument,
  useSignal,
  useStore,
  useVisibleTask$,
  type Signal,
} from "@qwik.dev/core";
import { useNavigate } from "@qwik.dev/router";
import {
  hasAuthenticatedConvexIdentity,
  useAuth,
} from "../../utils/auth-context";
import { useConvexClient } from "../../utils/convex-context";
import { api } from "../../../convex/_generated/api";
import { AuthPanel } from "./auth-panel";
import { Icon } from "../ui/icon";

interface AccountMenuProps {
  /**
   * Optional externally-controlled open state. When provided, the menu reads
   * and writes this signal so other UI (deep links, sign-in nudges) can open
   * it. When omitted, the menu manages its own open state internally.
   */
  open?: Signal<boolean>;
}

interface PendingInvitation {
  lixId: string;
  folioName: string;
  role: "editor" | "commenter";
  invitedAt: number;
}

interface SharedFolio {
  lixId: string;
  folioId: string;
  folioName: string;
  role: "editor" | "commenter";
  updatedAt: number;
}

/**
 * The Editor's Office — the account affordance shared across the app.
 *
 * Signed out, it's a single user icon that opens the sign-in panel. Signed in,
 * it shows the writer's name (and avatar, if their session carries one) with a
 * dropdown to Preferences, the Manual, and the AuthPanel (which holds sign-out).
 *
 * This is the exact control the editor toolbar uses; the landing header mounts
 * the same component so a signed-in writer sees a consistent account menu
 * instead of a "Sign in" link.
 */
export const AccountMenu = component$<AccountMenuProps>(({ open }) => {
  const auth = useAuth();
  const nav = useNavigate();
  const convexClient = useConvexClient();
  const internalOpen = useSignal(false);
  const profileAvatarUrl = useSignal<string | null>(null);
  const profileDisplay = useSignal<string | null>(null);
  const invitations = useStore<PendingInvitation[]>([]);
  const sharedFolios = useStore<SharedFolio[]>([]);
  const invitationError = useSignal<string | null>(null);
  const invitationBusy = useSignal<string | null>(null);
  // Pick the effective signal once. Signals are serializable across the QRL
  // boundary, so handlers can use `menuOpen.value` directly (closures can't).
  const menuOpen = open ?? internalOpen;
  const rootRef = useSignal<HTMLElement>();

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ track, cleanup }) => {
    const authState = track(auth);
    const client = track(() => convexClient.value);

    profileAvatarUrl.value = null;
    profileDisplay.value = null;
    invitations.splice(0, invitations.length);
    sharedFolios.splice(0, sharedFolios.length);
    if (!client || !hasAuthenticatedConvexIdentity(authState)) return;

    const replaceInvitations = (pending: PendingInvitation[]) => {
      invitations.splice(0, invitations.length, ...pending);
    };
    const replaceSharedFolios = (shared: SharedFolio[]) => {
      sharedFolios.splice(0, sharedFolios.length, ...shared);
    };
    const unsubscribeInvitations = client.onUpdate(
      api.collaboration.listPendingInvitations,
      {},
      replaceInvitations,
      () => undefined,
    );
    const unsubscribeShared = client.onUpdate(
      api.collaboration.listSharedWithMe,
      {},
      replaceSharedFolios,
      () => undefined,
    );
    cleanup(unsubscribeInvitations);
    cleanup(unsubscribeShared);

    const unsubscribeProfile = client.onUpdate(
      api.profiles.getMyHandle,
      {},
      (row) => {
        profileAvatarUrl.value = row?.avatarUrl ?? null;
        profileDisplay.value = row?.displayName || row?.handle || null;
      },
      () => undefined,
    );
    cleanup(unsubscribeProfile);
  });

  const rejectInvitation = $(async (lixId: string) => {
    const client = convexClient.value;
    if (!client) return;
    invitationBusy.value = lixId;
    invitationError.value = null;
    try {
      await client.mutation(api.collaboration.rejectInvitation, { lixId });
      const index = invitations.findIndex((invite) => invite.lixId === lixId);
      if (index >= 0) invitations.splice(index, 1);
    } catch {
      invitationError.value = "Could not decline that invitation. Try again.";
    } finally {
      invitationBusy.value = null;
    }
  });

  const accountDisplay = auth.value.user
    ? profileDisplay.value ||
      auth.value.user.name ||
      auth.value.user.email ||
      "Signed in"
    : null;
  const accountTitle = accountDisplay
    ? `Signed in as ${accountDisplay}`
    : "Editor's office";
  const avatar = profileAvatarUrl.value || auth.value.user?.image;

  // Close on outside click / Escape, matching dropdown conventions elsewhere.
  useOnDocument(
    "click",
    $((e) => {
      if (!menuOpen.value) return;
      const root = rootRef.value;
      const target = e.target as Node | null;
      if (root && target && !root.contains(target)) {
        menuOpen.value = false;
      }
    }),
  );
  useOnDocument(
    "keydown",
    $((e) => {
      if (menuOpen.value && (e as KeyboardEvent).key === "Escape") {
        menuOpen.value = false;
      }
    }),
  );

  return (
    <div class="relative" ref={rootRef}>
      <button
        onClick$={() => {
          menuOpen.value = !menuOpen.value;
        }}
        class={`icon-btn ${
          accountDisplay
            ? "gap-1.5 border border-[var(--color-sage)] bg-[var(--color-paper-soft)] px-2 py-1.5 text-[var(--color-ink)] hover:text-[var(--color-vermilion)]"
            : "p-1.5 text-[var(--color-ink-light)] hover:text-[var(--color-vermilion)]"
        }`}
        title={accountTitle}
        aria-label={
          accountDisplay
            ? `Open account menu. Signed in as ${accountDisplay}`
            : "Open the editor's office (account)"
        }
        aria-expanded={menuOpen.value}
      >
        {accountDisplay &&
          (avatar ? (
            <img
              src={avatar}
              alt=""
              width="20"
              height="20"
              class="h-5 w-5 flex-shrink-0 rounded-full object-cover"
              aria-hidden="true"
            />
          ) : (
            <span
              class="h-1.5 w-1.5 flex-shrink-0 rounded-full bg-[var(--color-sage)]"
              aria-hidden="true"
            />
          ))}
        {!avatar && <Icon name="user" size={18} />}
        {accountDisplay && (
          <span
            class="hidden max-w-[8.5rem] truncate text-[11px] font-semibold lg:inline"
            style={{ fontFamily: "var(--font-sans)" }}
          >
            {accountDisplay}
          </span>
        )}
      </button>
      {menuOpen.value && (
        <div
          class="absolute right-0 top-full mt-2 w-72 folio p-3 space-y-2"
          style="z-index: var(--z-dropdown);"
        >
          <div class="flex flex-col gap-1 pb-2 border-b border-[var(--color-paper-3)]">
            <button
              type="button"
              class="flex w-full items-center gap-2 text-left text-sm text-[var(--color-ink)] hover:text-[var(--color-vermilion)] py-1.5 px-2 focus-ring"
              style={{ fontFamily: "var(--font-display)" }}
              onClick$={() => {
                menuOpen.value = false;
                void nav("/settings/");
              }}
            >
              <Icon name="settings" size={16} /> Preferences
            </button>
            <button
              type="button"
              class="flex w-full items-center gap-2 text-left text-sm text-[var(--color-ink)] hover:text-[var(--color-vermilion)] py-1.5 px-2 focus-ring"
              style={{ fontFamily: "var(--font-display)" }}
              onClick$={() => {
                menuOpen.value = false;
                void nav("/desk/");
              }}
            >
              <Icon name="house" size={16} /> My Desk
            </button>
            <button
              type="button"
              class="flex w-full items-center gap-2 text-left text-sm text-[var(--color-ink)] hover:text-[var(--color-vermilion)] py-1.5 px-2 focus-ring"
              style={{ fontFamily: "var(--font-display)" }}
              onClick$={() => {
                menuOpen.value = false;
                void nav("/docs/");
              }}
            >
              <Icon name="book-open" size={16} /> The Manual
            </button>
            <button
              type="button"
              class="flex w-full items-center gap-2 text-left text-sm text-[var(--color-ink)] hover:text-[var(--color-vermilion)] py-1.5 px-2 focus-ring"
              style={{ fontFamily: "var(--font-display)" }}
              onClick$={() => {
                menuOpen.value = false;
                void nav("/privacy-ledger/");
              }}
            >
              <Icon name="shield-check" size={16} /> Privacy ledger
            </button>
          </div>
          {invitations.length > 0 && (
            <section class="space-y-2 border-b border-[var(--color-paper-3)] pb-3">
              <p
                class="px-2 text-[10px] font-semibold uppercase tracking-[0.12em] text-[var(--color-ink-light)]"
                style={{ fontFamily: "var(--font-sans)" }}
              >
                Invitations
              </p>
              {invitations.map((invitation) => (
                <div
                  key={invitation.lixId}
                  class="rounded-sm bg-[var(--color-paper-soft)] px-2.5 py-2"
                >
                  <p class="truncate text-sm text-[var(--color-ink)]">
                    {invitation.folioName}
                  </p>
                  <p class="mt-0.5 text-[11px] text-[var(--color-ink-light)]">
                    Invited as {invitation.role}
                  </p>
                  <div class="mt-2 flex items-center gap-2">
                    <button
                      type="button"
                      class="text-xs font-semibold text-[var(--color-vermilion)] hover:underline disabled:opacity-50"
                      disabled={invitationBusy.value === invitation.lixId}
                      onClick$={() => {
                        menuOpen.value = false;
                        void nav(
                          `/editor?shared=${encodeURIComponent(invitation.lixId)}`,
                        );
                      }}
                    >
                      Open
                    </button>
                    <button
                      type="button"
                      class="text-xs text-[var(--color-ink-light)] hover:text-[var(--color-ink)] disabled:opacity-50"
                      disabled={invitationBusy.value === invitation.lixId}
                      onClick$={() => rejectInvitation(invitation.lixId)}
                    >
                      Decline
                    </button>
                  </div>
                </div>
              ))}
              {invitationError.value && (
                <p
                  class="px-2 text-xs text-[var(--color-vermilion)]"
                  role="alert"
                >
                  {invitationError.value}
                </p>
              )}
            </section>
          )}
          {sharedFolios.length > 0 && (
            <section class="space-y-1 border-b border-[var(--color-paper-3)] pb-3">
              <p
                class="px-2 text-[10px] font-semibold uppercase tracking-[0.12em] text-[var(--color-ink-light)]"
                style={{ fontFamily: "var(--font-sans)" }}
              >
                Shared with me
              </p>
              {sharedFolios.map((folio) => (
                <button
                  key={folio.lixId}
                  type="button"
                  class="block w-full rounded-sm px-2.5 py-2 text-left hover:bg-[var(--color-paper-soft)] focus-ring"
                  onClick$={() => {
                    menuOpen.value = false;
                    void nav(
                      `/editor?shared=${encodeURIComponent(folio.lixId)}`,
                    );
                  }}
                >
                  <span class="block truncate text-sm text-[var(--color-ink)]">
                    {folio.folioName}
                  </span>
                  <span class="mt-0.5 block text-[11px] text-[var(--color-ink-light)]">
                    {folio.role === "editor" ? "Can edit" : "Can comment"}
                  </span>
                </button>
              ))}
            </section>
          )}
          <AuthPanel />
        </div>
      )}
    </div>
  );
});
import {
  component$,
  createContextId,
  Slot,
  useContext,
  useContextProvider,
  useSignal,
  useVisibleTask$,
  type Signal,
} from "@qwik.dev/core";
import { authClient } from "./auth-client";
import { createConvexTokenFetcher } from "./convex-token";
import { analyticsIdFromConvexJwt } from "./auth-analytics";
import { reportApplicationError } from "./application-diagnostics";
import { setConvexSyncContext, clearConvexSyncContext } from "./convex-sync";
import { useConvexClient } from "./convex-context";

export interface AuthUser {
  id: string;
  /** Stable identifier shared by browser and authenticated server analytics. */
  analyticsId?: string;
  email: string;
  name?: string;
  image?: string;
}

export interface AuthState {
  user: AuthUser | null;
  loading: boolean;
  /** True only after a Better Auth token has been installed in Convex. */
  convexAuthenticated?: boolean;
  /**
   * Restored ATProto OAuth session, used only to write records to a PDS.
   * It is never a Twyne identity; sign-in is Not Organic only.
   */
  atproto?: {
    did: string;
    handle: string;
    displayName?: string;
    avatar?: string;
  };
  /** Set once a Not Organic–backed Better Auth session is present. */
  provider?: "convex";
}

export const AuthContext =
  createContextId<Signal<AuthState>>("twyne.auth-context");

export function useAuth(): Signal<AuthState> {
  return useContext(AuthContext);
}

export function hasAuthenticatedConvexIdentity(state: AuthState): boolean {
  return (
    state.provider === "convex" &&
    state.convexAuthenticated === true &&
    state.user !== null
  );
}

export const AuthProvider = component$(() => {
  const authState = useSignal<AuthState>({ user: null, loading: true });
  const convexClient = useConvexClient();

  useContextProvider(AuthContext, authState);

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(
    async ({ cleanup, track }) => {
      track(convexClient);

      const convex = convexClient.value;
      let disposed = false;
      let currentUserId: string | null = null;
      let authGeneration = 0;
      let atproto: AuthState["atproto"];
      let atprotoPending = true;
      let betterAuthPending = true;
      const isAtprotoCallback = window.location.pathname === "/auth/callback/";
      let unsubscribe: (() => void) | undefined;
      cleanup(() => {
        disposed = true;
        authGeneration++;
        unsubscribe?.();
        clearConvexSyncContext();
      });

      const publishAtproto = () => {
        if (disposed) return;
        if (authState.value.provider === "convex") {
          authState.value = {
            ...authState.value,
            atproto,
            loading: isAtprotoCallback && atprotoPending,
          };
        } else {
          authState.value = {
            user: null,
            loading: betterAuthPending,
            atproto,
          };
        }
      };
      // A PDS publishing session must not delay the Twyne/Convex session.
      void import("./atproto").then(
        async ({ initSession, ATPROTO_SESSION_CHANGED }) => {
          if (disposed) return;
          const onSessionChange = () => {
            atproto = undefined;
            publishAtproto();
          };
          window.addEventListener(ATPROTO_SESSION_CHANGED, onSessionChange);
          cleanup(() =>
            window.removeEventListener(
              ATPROTO_SESSION_CHANGED,
              onSessionChange,
            ),
          );
          atproto = (await initSession()) ?? undefined;
          atprotoPending = false;
          publishAtproto();
        },
      );

      const sessionAtom = authClient.useSession;
      if (!sessionAtom || typeof sessionAtom !== "object") {
        betterAuthPending = false;
        return;
      }

      function syncFromAtom() {
        if (disposed) return;
        const val = sessionAtom.get?.() ?? sessionAtom;
        betterAuthPending = val?.isPending ?? false;
        const sessionData = val?.data;
        if (val?.isPending && !sessionData?.user) return;
        if (sessionData?.user) {
          if (currentUserId === sessionData.user.id) return;
          currentUserId = sessionData.user.id;
          const generation = ++authGeneration;
          const isCurrent = () => !disposed && generation === authGeneration;
          const user: AuthUser = {
            id: sessionData.user.id,
            // Not Organic users carry an undeliverable placeholder address.
            email: sessionData.user.email?.endsWith("@notorganic.invalid")
              ? ""
              : (sessionData.user.email ?? ""),
            name: sessionData.user.name ?? undefined,
            image: sessionData.user.image ?? undefined,
          };
          authState.value = {
            user,
            loading: isAtprotoCallback && atprotoPending,
            provider: "convex",
            convexAuthenticated: false,
            atproto,
          };
          clearConvexSyncContext();
          if (!convex) return;
          const fetchToken = createConvexTokenFetcher(async () => {
            try {
              const result = await (authClient as any).convex.token({
                fetchOptions: { throw: false },
              });
              const token = result?.data?.token ?? null;
              if (isCurrent())
                user.analyticsId = analyticsIdFromConvexJwt(token);
              return token;
            } catch (error) {
              if (isCurrent())
                reportApplicationError(
                  "twyne:auth:install-convex-token",
                  error,
                  {
                    source: "auth",
                    title: "Cloud sync is paused",
                    dedupeKey: "convex-auth",
                    metadata: { operation: "install-convex-token" },
                  },
                );
              return null;
            }
          }, isCurrent);
          convex.setAuth(fetchToken, (authenticated) => {
            if (!isCurrent()) return;
            authState.value = {
              user,
              loading: isAtprotoCallback && atprotoPending,
              provider: "convex",
              convexAuthenticated: authenticated,
              atproto,
            };
            if (authenticated) setConvexSyncContext(convex, user.id);
            else clearConvexSyncContext();
          });
        } else {
          currentUserId = null;
          authGeneration++;
          convex?.setAuth(async () => null);
          clearConvexSyncContext();
          authState.value = { user: null, loading: val?.isPending ?? false };
          publishAtproto();
        }
      }
      syncFromAtom();
      if (typeof sessionAtom.subscribe === "function") {
        unsubscribe = sessionAtom.subscribe(syncFromAtom);
      }
    },
    { strategy: "document-ready" },
  );

  return <Slot />;
});
