import { useEffect, useMemo, useState, type FormEvent } from "react";
import { portalApi, type SessionInfo } from "./api";
import { IntegrationsView } from "./views/Integrations";
import { ApplicationAdmin } from "./views/ApplicationAdmin";
import { ActivityView } from "./views/Activity";
import { SettingsView } from "./views/Settings";
import { UsageView } from "./views/Usage";

import { IdentityLight } from "./IdentityLight";
import { applyAppearance, PRODUCT_NAMES, type Product, type Theme } from "./appearance";

type View = "settings" | "usage" | "activity" | "admin" | "integrations";

const VIEWS: Array<{ id: View; label: string }> = [
  { id: "integrations", label: "Your apps" },
  { id: "settings", label: "Settings" },
  { id: "usage", label: "Usage" },
  { id: "activity", label: "Activity" },
];

/**
 * The company mark, identical to the one on notorganic.info: a rounded
 * teardrop rotated 45 degrees. It is drawn in CSS rather than loaded as an
 * asset so it renders at the same instant as the text beside it — this is the
 * element that tells someone the redirect landed where they expected, and it
 * arriving late is the one thing it must not do.
 */
function Wordmark() {
  return (
    <a className="wordmark" href="https://notorganic.info" aria-label="Not Organic home">
      <span className="mark" aria-hidden="true" />
      Not Organic
    </a>
  );
}

/**
 * Shows the typed handle back, shaped the way the system will read it.
 *
 * Sign-in is the step where people most often suspect they have mistyped
 * something, and the cost of being wrong is a confusing redirect to someone
 * else's provider. Echoing the input — with the initial in the avatar and the
 * normalised handle underneath — answers that doubt before they commit,
 * without a round trip.
 *
 * It only claims to normalise, never to verify. The handle is not resolved
 * until the form is submitted, so the label says "will sign in as" rather than
 * implying the account has been found.
 */
function HandleEcho({ handle }: { handle: string }) {
  const trimmed = handle.trim();
  const live = trimmed.length >= 3;

  const normalised = useMemo(() => {
    if (!live) return "";
    const value = trimmed.toLowerCase().replace(/^@/, "");
    // A DID is already canonical; anything else is a handle, and a bare name
    // with no dot is one the resolver will reject.
    if (value.startsWith("did:")) return value;
    return value;
  }, [trimmed, live]);

  const initial = live ? normalised.replace(/^did:\w+:/, "").charAt(0) : "?";

  return (
    <div className={live ? "handle-echo is-live" : "handle-echo"}>
      <span className="avatar" aria-hidden="true">
        <span>{initial}</span>
      </span>
      <span className="echo-text">
        <span className="echo-label">{live ? "Will sign in as" : "Waiting for a handle"}</span>
        <span className="echo-value">
          {live ? normalised : "you.pds.notorganic.info"}
        </span>
      </span>
    </div>
  );
}

function SignIn({ onSignedIn }: { onSignedIn: () => void }) {
  const [handle, setHandle] = useState("");
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const [creating, setCreating] = useState(false);
  const [mode, setMode] = useState(new URLSearchParams(window.location.search).get("action") === "signup" ? "signup" : "signin");
  const product = PRODUCT_NAMES[(document.documentElement.dataset.product ?? "notorganic") as Product] ?? "Not Organic";
  const chooseMode = (next: string) => {
    const url = new URL(window.location.href);
    url.searchParams.set("action", next);
    window.history.replaceState(null, "", url);
    setMode(next);
    setMessage("");
  };

  const signup = async () => {
    setBusy(true);
    setCreating(true);
    setMessage("Opening Not Organic account creation…");
    try {
      window.location.href = await portalApi.signup();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Could not start account creation.");
      setBusy(false);
      setCreating(false);
    }
  };

  // The callback route redirects back here with ?error= when sign-in fails.
  useEffect(() => {
    if (new URLSearchParams(window.location.search).get("error") === "signin_failed") {
      setMessage("Sign-in did not complete. Please try again.");
      const url = new URL(window.location.href);
      url.searchParams.delete("error");
      window.history.replaceState(null, "", url);
    }
  }, []);

  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setBusy(true);
    setMessage("Opening your account provider…");
    try {
      window.location.href = await portalApi.login(handle);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Sign-in failed");
      setBusy(false);
    }
  };

  // Present so a session established in another tab is picked up on focus.
  useEffect(() => {
    const check = () => void portalApi.session().then((session) => session && onSignedIn());
    window.addEventListener("focus", check);
    return () => window.removeEventListener("focus", check);
  }, [onSignedIn]);

  return (
    <section className="panel signin">
      <nav className="auth-options" aria-label="Account access">
        <button type="button" aria-pressed={mode === "signin"} disabled={busy} onClick={() => chooseMode("signin")}>Sign in</button>
        <button type="button" aria-pressed={mode === "signup"} disabled={busy} onClick={() => chooseMode("signup")}>Create account</button>
      </nav>
      <h2>{mode === "signup" ? "Create your Not Organic account" : "Welcome back"}</h2>
      <p>{product === "Not Organic" ? "One account for Twyne, Keating, Interleave, and Stich." : `Continue with ${product}, using your Not Organic account.`}</p>
      {mode === "signup" ? <>
        <p>Choose a handle and password to get started. Your account works across all four apps.</p>
        <div className="button-row">
          <button className="primary" type="button" disabled={busy} onClick={() => void signup()}>
            {creating ? "Opening account creation…" : "Create account"}
          </button>
        </div>
      </> : <>
      <p>Enter your account handle to sign in securely.</p>
      <form onSubmit={submit}>
        <label>
          Account handle
          <input
            value={handle}
            onChange={(event) => setHandle(event.target.value)}
            placeholder="you.pds.notorganic.info"
            autoComplete="username"
            autoCapitalize="none"
            spellCheck={false}
            required
          />
        </label>
        <HandleEcho handle={handle} />
        <div className="button-row">
          <button type="submit" disabled={busy || handle.trim().length < 3}>
            Sign in
          </button>
        </div>
      </form>
      </>}
      <output aria-live="polite">{message}</output>
      <p className="signin-legal"><a href="https://notorganic.info/terms">Terms</a><span aria-hidden="true"> · </span><a href="https://notorganic.info/privacy">Privacy</a><span aria-hidden="true"> · </span><a href="https://notorganic.info/services#support">Help</a></p>
    </section>
  );
}

function initialView(): View {
