import { useEffect, useRef } from "react";
import type { Product } from "./appearance";
import { IDENTITY_SHADERS } from "../../landing/product-shaders.js";

const VERTEX_SHADER = `
attribute vec2 aPosition;
void main() { gl_Position = vec4(aPosition, 0.0, 1.0); }
`;


export function IdentityLight({ product }: { product: Product }) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const motion = matchMedia("(prefers-reduced-motion: reduce)");
    if (motion.matches) return;
    const gl = canvas.getContext("webgl", { alpha: false, antialias: false, depth: false });
    if (!gl) return;
    const program = gl.createProgram();
    if (!program) return;
    const shaders: WebGLShader[] = [];
    for (const [type, source] of [[gl.VERTEX_SHADER, VERTEX_SHADER], [gl.FRAGMENT_SHADER, IDENTITY_SHADERS[product].source]] as const) {
      const shader = gl.createShader(type);
      if (!shader) return;
      gl.shaderSource(shader, source); gl.compileShader(shader);
      if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) { gl.deleteShader(shader); gl.deleteProgram(program); return; }
      gl.attachShader(program, shader); shaders.push(shader);
    }
    gl.linkProgram(program);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) { shaders.forEach(s => gl.deleteShader(s)); gl.deleteProgram(program); return; }
    gl.useProgram(program);
    const buffer = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1,-1,3,-1,-1,3]), gl.STATIC_DRAW);
    const position = gl.getAttribLocation(program, "aPosition"); gl.enableVertexAttribArray(position); gl.vertexAttribPointer(position,2,gl.FLOAT,false,0,0);
    const resolution = gl.getUniformLocation(program,"uResolution");
    const time = gl.getUniformLocation(program,"uTime");
    gl.uniform2f(gl.getUniformLocation(program,"uPointer"),.5,.5);
    let frame = 0; let visible = true;
    const resize = () => { const ratio = Math.min(devicePixelRatio,1.25); canvas.width = Math.max(1,Math.round(canvas.clientWidth*ratio)); canvas.height = Math.max(1,Math.round(canvas.clientHeight*ratio)); gl.viewport(0,0,canvas.width,canvas.height); gl.uniform2f(resolution,canvas.width,canvas.height); };
    const draw = (now: number) => { gl.uniform1f(time,now/1000); gl.drawArrays(gl.TRIANGLES,0,3); frame = requestAnimationFrame(draw); };
    const sync = () => { cancelAnimationFrame(frame); if (visible && !document.hidden && !motion.matches) frame = requestAnimationFrame(draw); };
    const observer = new ResizeObserver(resize); observer.observe(canvas); resize();
    const visibility = new IntersectionObserver(([entry]) => { visible = entry?.isIntersecting ?? false; sync(); }); visibility.observe(canvas);
    motion.addEventListener("change",sync); document.addEventListener("visibilitychange",sync); sync();
    canvas.dataset.ready = "true";
    return () => { cancelAnimationFrame(frame); observer.disconnect(); visibility.disconnect(); motion.removeEventListener("change",sync); document.removeEventListener("visibilitychange",sync); gl.deleteBuffer(buffer); shaders.forEach(s => gl.deleteShader(s)); gl.deleteProgram(program); };
  }, [product]);
  return <canvas ref={ref} className="identity-light" data-shader={IDENTITY_SHADERS[product].name} aria-hidden="true" />;
}
import { useCallback, useEffect, useState, type ReactNode } from "react";
import { useReveal } from "./juice";

export function Panel({
  title,
  eyebrow,
  children,
  wide,
  /** Position in the view, so sibling panels arrive in sequence. */
  index = 0,
}: {
  title: string;
  eyebrow: string;
  children: ReactNode;
  wide?: boolean;
  index?: number;
}) {
  const ref = useReveal<HTMLElement>(index);
  return (
    <section ref={ref} className={wide ? "panel panel-wide" : "panel"}>
      <p className="eyebrow">{eyebrow}</p>
      <h2>{title}</h2>
      {children}
    </section>
  );
}

export function useOperation() {
  const [message, setMessage] = useState("");
  const run = async (operation: () => Promise<unknown>, success: string) => {
    setMessage("Working…");
    try {
      await operation();
      setMessage(success);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Request failed");
    }
  };
  return { message, run, setMessage };
}

/** Loads once on mount and exposes a manual refresh. */
export function useLoader<T>(load: () => Promise<T>, deps: unknown[] = []) {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    setLoading(true);
    try {
      setData(await load());
      setError("");
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Request failed");
    } finally {
      setLoading(false);
    }
    // `load` is redefined per render by callers; deps are supplied explicitly.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  return { data, error, loading, refresh };
}

/** All money in this system is integer micro-USD; 1_000_000 = $1. */
export function usd(micros: number | undefined): string {
  return `$${((micros ?? 0) / 1_000_000).toFixed(4).replace(/0+$/, "").replace(/\.$/, ".00")}`;
}

/**
 * Two decimals, for the headline balance only.
 *
 * `usd` above keeps four, because a single metered request can cost a fraction
 * of a cent and rounding those away in the usage table would make the column
 * fail to add up. A headline figure has the opposite problem: it is animated,
 * and four decimals rolling at 60fps is an unreadable blur of digits. The
 * precise figures stay one line below it.
 */
export function usdRounded(micros: number | undefined): string {
  return `$${((micros ?? 0) / 1_000_000).toFixed(2)}`;
}

export function timestamp(value: number | undefined): string {
  if (!value) return "—";
  return new Date(value).toLocaleString();
}

export function duration(from: number | undefined, to: number | undefined): string {
  if (!from || !to || to < from) return "—";
  const seconds = Math.round((to - from) / 1000);
  return seconds < 60 ? `${seconds}s` : `${Math.floor(seconds / 60)}m ${seconds % 60}s`;
}

/**
 * Product ids are stable machine values (`twyne`, `stich`) and plan ids carry
 * an underscore (`twyne_pro`). Neither is how the product is written down
 * anywhere else the customer has seen it — not on the invoice, not on the
 * marketing site, not in the app they bought it in. Printing the raw id here
 * makes the portal look like a database viewer and quietly asks the reader to
 * learn a second name for something they already know.
 */
const PRODUCT_NAMES: Record<string, string> = {
  twyne: "Twyne",
  keating: "Keating",
  interleave: "Interleave",
  stich: "Stich",
  notorganic: "Not Organic",
};

export function productLabel(product: string): string {
  return PRODUCT_NAMES[product] ?? titleCase(product);
}

/** `twyne_pro` becomes "Twyne Pro", with the product's real capitalisation. */
export function planLabel(plan: string): string {
  const [head, ...rest] = plan.split("_");
  const product = head ? (PRODUCT_NAMES[head] ?? titleCase(head)) : "";
  return [product, ...rest.map(titleCase)].filter(Boolean).join(" ");
}

function titleCase(value: string): string {
  return value
    .split(/[_\s-]+/)
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(" ");
}

/**
 * Status as a word rather than an enum. `past_due` is a state the reader is
 * being asked to act on, and PAST_DUE reads as a log line — something that
 * happened to the system — rather than something about their account.
 *
 * Tone is a scan aid only. The word inside the pill always carries the
 * meaning, so the state survives a monochrome render and does not depend on
 * the reader distinguishing amber from green.
 */
export function StatusPill({ status }: { status: string }) {
  const tone =
    status === "succeeded" || status === "active"
      ? "good"
      : status === "failed" || status === "expired" || status === "locked"
        ? "bad"
        : status === "cancelled"
          ? "muted"
          : "busy";
  return <span className={`pill pill-${tone}`}>{titleCase(status)}</span>;
}

export function Empty({ children }: { children: ReactNode }) {
  return <p className="empty">{children}</p>;
}
import { useState } from "react";
import type {
  ProjectCiConfig,
  ProjectExecutionConfig,
  ProjectSourceConfig,
} from "@notorganic/contracts";
import { portalApi, type AccountView } from "../api";
import {
  Empty,
  Panel,
  planLabel,
  productLabel,
  StatusPill,
  timestamp,
  useLoader,
  useOperation,
} from "../ui";

function Identity({ account }: { account: AccountView }) {
  if (!account.account) {
    return <Empty>No provider account is linked to this DID yet.</Empty>;
  }
  const { did, handle, pdsUrl, recoveryState, createdAt } = account.account;
  return (
    <dl className="overview">
      <div>
        <dt>Handle</dt>
        <dd>{handle ?? "—"}</dd>
      </div>
      <div>
        <dt>DID</dt>
        <dd className="break">
          <code>{did}</code>
        </dd>
      </div>
      <div>
        <dt>PDS</dt>
        <dd className="break">{pdsUrl}</dd>
      </div>
      <div>
        <dt>Recovery</dt>
        <dd>
          <StatusPill status={recoveryState} />
        </dd>
      </div>
      <div>
        <dt>Member since</dt>
        <dd>{timestamp(createdAt)}</dd>
      </div>
    </dl>
  );
}

/**
 * Mirrors the one cross-field rule in `ProjectExecutionConfigSchema`, so the
 * reader sees why a combination is refused before the request is made. The
 * gateway remains the authority.
 */
function ciBlockedReason(source: ProjectSourceConfig, ci: ProjectCiConfig): string | null {
  if (ci.mode !== "disabled" && source.mode === "pds") {
    return "Spindle CI needs a Tangled repository. Choose a managed or external source first.";
  }
  return null;
}

function ProjectEditor({
  project,
  onSaved,
}: {
  project: ProjectExecutionConfig;
  onSaved: () => void;
}) {
  const [source, setSource] = useState<ProjectSourceConfig>(project.source);
  const [mirror, setMirror] = useState(project.source_mirror);
  const [ci, setCi] = useState<ProjectCiConfig>(project.ci);
  const [retention, setRetention] = useState(project.artifacts.retention_days);
  const save = useOperation();

  const blocked = ciBlockedReason(source, ci);
  const dirty =
    JSON.stringify({ source, mirror, ci, retention }) !==
    JSON.stringify({
      source: project.source,
      mirror: project.source_mirror,
      ci: project.ci,
      retention: project.artifacts.retention_days,
    });

  const submit = () =>
    void save.run(async () => {
      await portalApi.updateProject(project.project_id, {
        source,
        source_mirror: mirror,
        ci,
        artifacts: { provider: "r2", retention_days: retention },
      });
      onSaved();
    }, "Saved.");

  return (
    <li className="project">
      <div className="run-head">
        <strong>{project.project_id}</strong>
        <small className="hint">{productLabel(project.product)}</small>
      </div>

      <label>
        Source
        <select
          value={source.mode}
          onChange={(event) => {
            const mode = event.target.value as ProjectSourceConfig["mode"];
            setSource(mode === "tangled_external" ? { mode, repo_uri: "" } : { mode });
          }}
        >
          <option value="pds">PDS only</option>
          <option value="tangled_managed">Notorganic-managed Tangled repository</option>
          <option value="tangled_external">My own Tangled repository</option>
        </select>
      </label>
      {source.mode === "tangled_external" && (
        <label>
          Repository AT-URI
          <input
            value={source.repo_uri}
            placeholder="at://did:plc:…/sh.tangled.repo/name"
            onChange={(event) => setSource({ mode: "tangled_external", repo_uri: event.target.value })}
          />
        </label>
      )}

      <label>
        Source mirroring
        <select value={mirror} onChange={(event) => setMirror(event.target.value as typeof mirror)}>
          <option value="disabled">Disabled</option>
          <option value="r2">Commit-pinned archive in R2</option>
        </select>
      </label>

      <label>
        CI trigger
        <select
          value={ci.mode}
          onChange={(event) => {
            const mode = event.target.value as ProjectCiConfig["mode"];
            if (mode === "spindle_managed") setCi({ mode, runner: "cloudflare_sandbox" });
            else if (mode === "spindle_external") setCi({ mode, spindle_uri: "" });
            else setCi({ mode: "disabled" });
          }}
        >
          <option value="disabled">Disabled</option>
          <option value="spindle_managed">Notorganic-managed Spindle</option>
          <option value="spindle_external">My own Spindle</option>
        </select>
      </label>
      {ci.mode === "spindle_managed" && (
        <label>
          Managed runner
          <select
            value={ci.runner}
            onChange={(event) =>
              setCi({ mode: "spindle_managed", runner: event.target.value as "cloudflare_sandbox" | "fly_sprite" })
            }
          >
            <option value="cloudflare_sandbox">Cloudflare Sandbox</option>
            <option value="fly_sprite">Disposable Fly Sprite</option>
          </select>
        </label>
      )}
      {ci.mode === "spindle_external" && (
        <label>
          Spindle AT-URI
          <input
            value={ci.spindle_uri}
            placeholder="at://did:plc:…/sh.tangled.spindle/name"
            onChange={(event) => setCi({ mode: "spindle_external", spindle_uri: event.target.value })}
          />
        </label>
      )}

      <label>
        Artifact retention (days)
        <input
          type="number"
          min={1}
          max={3650}
          value={retention}
          onChange={(event) => setRetention(Number(event.target.value))}
        />
      </label>

      {blocked && <p className="notice notice-bad">{blocked}</p>}
      <div className="button-row">
        <button disabled={!dirty || blocked !== null} onClick={submit}>
          Save changes
        </button>
      </div>
      <output>{save.message}</output>
    </li>
  );
}

export function SettingsView() {
  const account = useLoader(() => portalApi.account(), []);
  const projects = useLoader(() => portalApi.projects(), []);

  return (
    <div className="grid">
      <Panel index={0} eyebrow="Identity" title="Your account">
        {account.error && <p className="notice notice-bad">{account.error}</p>}
        {account.loading && !account.data ? (
          <Empty>Loading…</Empty>
        ) : account.data ? (
          <Identity account={account.data} />
        ) : null}
      </Panel>

      <Panel index={1} eyebrow="Where you use it" title="Products and plans">
        {account.data && account.data.products.length === 0 && (
          <Empty>No products connected yet.</Empty>
        )}
        {account.data && account.data.products.length > 0 && (
          <>
            <p className="group-label">Products</p>
            <ul className="version-list">
              {account.data.products.map((product) => (
                <li key={product.product}>
                  <strong>{productLabel(product.product)}</strong>
                  <StatusPill status={product.status} />
                </li>
              ))}
            </ul>
          </>
        )}
        {account.data && account.data.subscriptions.length > 0 && (
          <>
            <p className="group-label">Plans you pay for</p>
            <ul className="version-list">
              {account.data.subscriptions.map((subscription) => (
                <li key={`${subscription.plan}-${subscription.status}`}>
                  <strong>{planLabel(subscription.plan)}</strong>
                  <StatusPill status={subscription.status} />
                  {subscription.currentPeriodEnd && (
                    <small className="hint">
                      Renews {timestamp(subscription.currentPeriodEnd)}
                    </small>
                  )}
                </li>
              ))}
            </ul>
          </>
        )}
        <p className="hint">
          Top-ups and plan changes happen in the product you bought them from. Your wallet is shared
          across all of them.
        </p>
      </Panel>

      <Panel index={2} eyebrow="Execution" title="Project configuration" wide>
        {projects.error && <p className="notice notice-bad">{projects.error}</p>}
        {projects.loading && !projects.data ? (
          <Empty>Loading…</Empty>
        ) : (projects.data ?? []).length === 0 ? (
          <Empty>
            No projects configured yet. A project appears here once a product creates one for you.
          </Empty>
        ) : (
          <ul className="project-list">
            {(projects.data ?? []).map((project) => (
              <ProjectEditor
                key={`${project.product}-${project.project_id}`}
                project={project}
                onSaved={() => void projects.refresh()}
              />
            ))}
          </ul>
        )}
        <p className="hint">
          Managed Tangled hosting is a collaboration home, not an artifact store. Build artifacts
          always land in Notorganic-managed R2 with the retention set here.
        </p>
      </Panel>
    </div>
  );
}
