    if ((requested === "integrations" || requested === "admin")) sessionStorage.setItem("notorganic-entry-view", requested);
    if ((requested === "integrations" || requested === "admin") || ["integrations","admin"].includes(sessionStorage.getItem("notorganic-entry-view") ?? "")) return requested === "admin" || sessionStorage.getItem("notorganic-entry-view") === "admin" ? "admin" : "integrations";
  } catch { /* Storage can be unavailable; direct links still work. */ }
  return requested === "admin" ? "admin" : requested === "integrations" ? "integrations" : "settings";
}
