import { createAuthClient } from "better-auth/client";
import {
  convexClient,
  crossDomainClient,
} from "@convex-dev/better-auth/client/plugins";
import { isDev } from "@qwik.dev/core/build";

const convexSiteUrl = import.meta.env.VITE_CONVEX_SITE_URL as
  | string
  | undefined;

/* ── Dev-mode passthrough ──
 * In local dev the Convex backend isn't wired up. Return a no-op client so
 * auth never blocks any UI or throws network errors. */
const mockClient = {
  useSession: {
    get: () => ({ data: null, isPending: false }),
    subscribe: () => () => {},
  },
  signOut: async () => {},
} as any;

export const authClient =
  isDev && !convexSiteUrl
    ? mockClient
    : createAuthClient({
        baseURL: convexSiteUrl,
        plugins: [
          // `crossDomainClient()` ships a `getActions` signature that
          // drifts from the `BetterAuthClientPlugin` constraint in this
          // better-auth version. The runtime contract is fine; suppress
          // the structural-typing noise.
          crossDomainClient() as any,
          convexClient(),
        ],
      });

export const { signOut, useSession } = authClient;
import { describe, expect, test } from "bun:test";
import { hasAuthenticatedConvexIdentity, type AuthState } from "./auth-context";

const productUser = {
  id: "user-1",
  email: "writer@example.com",
};

describe("Convex authentication state", () => {
  test("requires both the product session and installed Convex token", () => {
    const cases: Array<[AuthState, boolean]> = [
      [
        {
          user: productUser,
          loading: false,
          provider: "convex",
          convexAuthenticated: true,
        },
        true,
      ],
      [
        {
          user: productUser,
          loading: false,
          provider: "convex",
          convexAuthenticated: false,
        },
        false,
      ],
      [{ user: null, loading: false }, false],
    ];

    for (const [state, expected] of cases) {
      expect(hasAuthenticatedConvexIdentity(state)).toBe(expected);
    }
  });
});

