import type { CiRun, ProjectExecutionConfig, SandboxRun } from "@notorganic/contracts";

/**
 * The customer-facing portal API.
 *
 * Every call is same-origin against the portal's own server, authenticated by
 * an httpOnly session cookie. There is deliberately no token handling here:
 * gateway access tokens, DPoP keys, and the assertion key live in the portal
 * server and are never sent to the browser.
 */

export interface SessionInfo {
  authenticated: true;
  isAdmin?: boolean;
  did: string;
  csrfToken: string;
  expiresAt: number;
}

export interface AccountView {
  account: {
    did: string;
    handle?: string;
    pdsUrl: string;
    recoveryState: "active" | "pending" | "locked";
    createdAt: number;
    deletedAt?: number;
  } | null;
  products: Array<{ product: string; status: string; productAccountId: string }>;
  subscriptions: Array<{ plan: string; status: string; currentPeriodEnd?: number }>;
}

export interface WalletView {
  currency: "USD_MICROS";
  balanceMicros: number;
  reservedMicros: number;
  debtMicros: number;
  availableGrantMicros: number;
  hostedInferenceBlocked: boolean;
}

export interface UsageRow {
  _id: string;
  requestId: string;
  product: string;
  feature: string;
  model: string;
  state: "reserved" | "running" | "succeeded" | "failed" | "expired";
  inputTokens?: number;
  outputTokens?: number;
  billedMicros?: number;
  providerAbsorbedMicros?: number;
  errorCode?: string;
  reconciliationReason?: string;
  createdAt: number;
  completedAt?: number;
}

export interface ActivityView {
  sandbox: SandboxRun[];
  ci: CiRun[];
}

interface ListResponse<T> {
  object: "list";
  data: T[];
}

export class PortalApiError extends Error {
  constructor(message: string, readonly status: number, readonly code?: string) {
    super(message);
    this.name = "PortalApiError";
  }
}

let csrfToken: string | null = null;

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const method = (init?.method ?? "GET").toUpperCase();
  const response = await fetch(path, {
    ...init,
    credentials: "same-origin",
    headers: {
      accept: "application/json",
      ...(init?.body ? { "content-type": "application/json" } : {}),
      ...(method !== "GET" && csrfToken ? { "x-csrf-token": csrfToken } : {}),
      ...init?.headers,
    },
  });
  const text = await response.text();
  const payload = text ? (JSON.parse(text) as unknown) : null;
  if (!response.ok) {
    const error = (payload as { error?: { message?: string; code?: string } } | null)?.error;
    throw new PortalApiError(
      error?.message ?? `${response.status} ${response.statusText}`,
      response.status,
      error?.code,
    );
  }
  return payload as T;
}

export const portalApi = {
  /** Resolves to null when nobody is signed in, rather than throwing. */
  async session(): Promise<SessionInfo | null> {
    try {
      const session = await request<SessionInfo>("/api/session");
      csrfToken = session.csrfToken;
      return session;
    } catch (error) {
      if (error instanceof PortalApiError && error.status === 401) return null;
      throw error;
    }
  },

  /** Returns the authorization URL the browser should navigate to. */
  async login(handle: string): Promise<string> {
    const { redirectUrl } = await request<{ redirectUrl: string }>("/api/auth/login", {
      method: "POST",
      body: JSON.stringify({ handle }),
    });
    return redirectUrl;
  },

  async signup(): Promise<string> {
    const { redirectUrl } = await request<{ redirectUrl: string }>("/api/auth/signup", {
      method: "POST",
    });
    return redirectUrl;
  },

  async logout(): Promise<void> {
    await request("/api/auth/logout", { method: "POST" });
    csrfToken = null;
  },

  adminApplications: (cursor?:string) => request<{page:import("./views/ApplicationAdmin").Application[];isDone:boolean;continueCursor:string}>(`/api/admin/applications${cursor?`?cursor=${encodeURIComponent(cursor)}`:""}`),
  adminReview: (id:string,input:{expectedUpdatedAt:number;status:"pending"|"approved"|"rejected";note:string}) => request(`/api/admin/applications/${encodeURIComponent(id)}/review`,{method:"POST",body:JSON.stringify(input)}),
  adminHistory: (id:string) => request<Array<{actor:string;reason:string;createdAt:number}>>(`/api/admin/applications/${encodeURIComponent(id)}/history`),
  integrations: () => request<Array<{ _id: string; appName: string; origin: string; status: string; reviewNote?: string }>>("/api/integrations"),
  submitIntegration: (input: { appName: string; origin: string; callbackUrl: string; contactEmail: string; description: string }) => request<{ id: string; status: string }>("/api/integrations", { method: "POST", body: JSON.stringify(input) }),
  account: () => request<AccountView>("/api/account"),
  wallet: () => request<WalletView>("/api/wallet"),

  usage: (limit = 25) =>
    request<ListResponse<UsageRow>>(`/api/usage?limit=${limit}`).then((page) => page.data),

  activity: (limit = 25) => request<ActivityView>(`/api/activity?limit=${limit}`),

  projects: () =>
    request<ListResponse<ProjectExecutionConfig>>("/api/projects").then((page) => page.data),

  updateProject: (projectId: string, config: Omit<ProjectExecutionConfig, "project_id" | "product">) =>
    request<ProjectExecutionConfig>(
      `/api/projects/${encodeURIComponent(projectId)}/execution-config`,
      { method: "PUT", body: JSON.stringify(config) },
    ),
};

