      </div>
      <div>
        <dt>DID</dt>
        <dd className="break">
          <code>{did}</code>
        </dd>
      </div>
      <div>
        <dt>PDS</dt>
        <dd className="break">{pdsUrl}</dd>
      </div>
      <div>
        <dt>Recovery</dt>
        <dd>
          <StatusPill status={recoveryState} />
        </dd>
      </div>
      <div>
        <dt>Member since</dt>
        <dd>{timestamp(createdAt)}</dd>
      </div>
    </dl>
  );
}

/**
 * Mirrors the one cross-field rule in `ProjectExecutionConfigSchema`, so the
 * reader sees why a combination is refused before the request is made. The
 * gateway remains the authority.
 */
function ciBlockedReason(source: ProjectSourceConfig, ci: ProjectCiConfig): string | null {
  if (ci.mode !== "disabled" && source.mode === "pds") {
    return "Spindle CI needs a Tangled repository. Choose a managed or external source first.";
  }
  return null;
}

function ProjectEditor({
  project,
  onSaved,
}: {
  project: ProjectExecutionConfig;
  onSaved: () => void;
}) {
  const [source, setSource] = useState<ProjectSourceConfig>(project.source);
  const [mirror, setMirror] = useState(project.source_mirror);
  const [ci, setCi] = useState<ProjectCiConfig>(project.ci);
  const [retention, setRetention] = useState(project.artifacts.retention_days);
  const save = useOperation();

  const blocked = ciBlockedReason(source, ci);
  const dirty =
    JSON.stringify({ source, mirror, ci, retention }) !==
    JSON.stringify({
      source: project.source,
      mirror: project.source_mirror,
      ci: project.ci,
      retention: project.artifacts.retention_days,
    });

  const submit = () =>
    void save.run(async () => {
