          <option value="disabled">Disabled</option>
          <option value="spindle_managed">Notorganic-managed Spindle</option>
          <option value="spindle_external">My own Spindle</option>
        </select>
      </label>
      {ci.mode === "spindle_managed" && (
        <label>
          Managed runner
          <select
            value={ci.runner}
            onChange={(event) =>
              setCi({ mode: "spindle_managed", runner: event.target.value as "cloudflare_sandbox" | "fly_sprite" })
            }
          >
            <option value="cloudflare_sandbox">Cloudflare Sandbox</option>
            <option value="fly_sprite">Disposable Fly Sprite</option>
          </select>
        </label>
      )}
      {ci.mode === "spindle_external" && (
        <label>
          Spindle AT-URI
          <input
            value={ci.spindle_uri}
            placeholder="at://did:plc:…/sh.tangled.spindle/name"
            onChange={(event) => setCi({ mode: "spindle_external", spindle_uri: event.target.value })}
          />
        </label>
      )}

      <label>
        Artifact retention (days)
        <input
          type="number"
          min={1}
          max={3650}
          value={retention}
          onChange={(event) => setRetention(Number(event.target.value))}
        />
      </label>

      {blocked && <p className="notice notice-bad">{blocked}</p>}
      <div className="button-row">
        <button disabled={!dirty || blocked !== null} onClick={submit}>
          Save changes
        </button>
      </div>
      <output>{save.message}</output>
    </li>
  );
}

