import { useEffect, useMemo, useState, type FormEvent } from "react";
import { portalApi, type SessionInfo } from "./api";
import { IntegrationsView } from "./views/Integrations";
import { ApplicationAdmin } from "./views/ApplicationAdmin";
import { ActivityView } from "./views/Activity";
import { SettingsView } from "./views/Settings";
import { UsageView } from "./views/Usage";

import { IdentityLight } from "./IdentityLight";
import { applyAppearance, PRODUCT_NAMES, type Product, type Theme } from "./appearance";

type View = "settings" | "usage" | "activity" | "admin" | "integrations";

const VIEWS: Array<{ id: View; label: string }> = [
  { id: "integrations", label: "Your apps" },
  { id: "settings", label: "Settings" },
  { id: "usage", label: "Usage" },
  { id: "activity", label: "Activity" },
];

/**
 * The company mark, identical to the one on notorganic.info: a rounded
 * teardrop rotated 45 degrees. It is drawn in CSS rather than loaded as an
 * asset so it renders at the same instant as the text beside it — this is the
 * element that tells someone the redirect landed where they expected, and it
 * arriving late is the one thing it must not do.
 */
function Wordmark() {
  return (
    <a className="wordmark" href="https://notorganic.info" aria-label="Not Organic home">
      <span className="mark" aria-hidden="true" />
      Not Organic
    </a>
  );
}

/**
 * Shows the typed handle back, shaped the way the system will read it.
 *
 * Sign-in is the step where people most often suspect they have mistyped
 * something, and the cost of being wrong is a confusing redirect to someone
 * else's provider. Echoing the input — with the initial in the avatar and the
 * normalised handle underneath — answers that doubt before they commit,
 * without a round trip.
 *
 * It only claims to normalise, never to verify. The handle is not resolved
 * until the form is submitted, so the label says "will sign in as" rather than
 * implying the account has been found.
 */
function HandleEcho({ handle }: { handle: string }) {
  const trimmed = handle.trim();
  const live = trimmed.length >= 3;

  const normalised = useMemo(() => {
    if (!live) return "";
    const value = trimmed.toLowerCase().replace(/^@/, "");
    // A DID is already canonical; anything else is a handle, and a bare name
    // with no dot is one the resolver will reject.
    if (value.startsWith("did:")) return value;
    return value;
  }, [trimmed, live]);

  const initial = live ? normalised.replace(/^did:\w+:/, "").charAt(0) : "?";

  return (
    <div className={live ? "handle-echo is-live" : "handle-echo"}>
      <span className="avatar" aria-hidden="true">
        <span>{initial}</span>
      </span>
      <span className="echo-text">
        <span className="echo-label">{live ? "Will sign in as" : "Waiting for a handle"}</span>
        <span className="echo-value">
          {live ? normalised : "you.pds.notorganic.info"}
        </span>
      </span>
    </div>
  );
}

function SignIn({ onSignedIn }: { onSignedIn: () => void }) {
  const [handle, setHandle] = useState("");
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const [creating, setCreating] = useState(false);
  const [mode, setMode] = useState(new URLSearchParams(window.location.search).get("action") === "signup" ? "signup" : "signin");
  const product = PRODUCT_NAMES[(document.documentElement.dataset.product ?? "notorganic") as Product] ?? "Not Organic";
  const chooseMode = (next: string) => {
    const url = new URL(window.location.href);
    url.searchParams.set("action", next);
    window.history.replaceState(null, "", url);
    setMode(next);
    setMessage("");
  };

  const signup = async () => {
    setBusy(true);
    setCreating(true);
    setMessage("Opening Not Organic account creation…");
    try {
      window.location.href = await portalApi.signup();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Could not start account creation.");
      setBusy(false);
      setCreating(false);
    }
  };

  // The callback route redirects back here with ?error= when sign-in fails.
  useEffect(() => {
    if (new URLSearchParams(window.location.search).get("error") === "signin_failed") {
      setMessage("Sign-in did not complete. Please try again.");
      const url = new URL(window.location.href);
      url.searchParams.delete("error");
      window.history.replaceState(null, "", url);
    }
  }, []);

  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setBusy(true);
    setMessage("Opening your account provider…");
    try {
      window.location.href = await portalApi.login(handle);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Sign-in failed");
      setBusy(false);
    }
  };

  // Present so a session established in another tab is picked up on focus.
  useEffect(() => {
    const check = () => void portalApi.session().then((session) => session && onSignedIn());
    window.addEventListener("focus", check);
    return () => window.removeEventListener("focus", check);
  }, [onSignedIn]);

  return (
    <section className="panel signin">
      <nav className="auth-options" aria-label="Account access">
        <button type="button" aria-pressed={mode === "signin"} disabled={busy} onClick={() => chooseMode("signin")}>Sign in</button>
        <button type="button" aria-pressed={mode === "signup"} disabled={busy} onClick={() => chooseMode("signup")}>Create account</button>
      </nav>
      <h2>{mode === "signup" ? "Create your Not Organic account" : "Welcome back"}</h2>
      <p>{product === "Not Organic" ? "One account for Twyne, Keating, Interleave, and Stich." : `Continue with ${product}, using your Not Organic account.`}</p>
      {mode === "signup" ? <>
        <p>Choose a handle and password to get started. Your account works across all four apps.</p>
        <div className="button-row">
          <button className="primary" type="button" disabled={busy} onClick={() => void signup()}>
            {creating ? "Opening account creation…" : "Create account"}
          </button>
        </div>
      </> : <>
      <p>Enter your account handle to sign in securely.</p>
      <form onSubmit={submit}>
        <label>
          Account handle
          <input
            value={handle}
            onChange={(event) => setHandle(event.target.value)}
            placeholder="you.pds.notorganic.info"
            autoComplete="username"
            autoCapitalize="none"
            spellCheck={false}
            required
          />
        </label>
        <HandleEcho handle={handle} />
        <div className="button-row">
          <button type="submit" disabled={busy || handle.trim().length < 3}>
            Sign in
          </button>
        </div>
      </form>
      </>}
      <output aria-live="polite">{message}</output>
      <p className="signin-legal"><a href="https://notorganic.info/terms">Terms</a><span aria-hidden="true"> · </span><a href="https://notorganic.info/privacy">Privacy</a><span aria-hidden="true"> · </span><a href="https://notorganic.info/services#support">Help</a></p>
    </section>
  );
}

function initialView(): View {
  const requested = new URLSearchParams(location.search).get("view");
  try {
    if ((requested === "integrations" || requested === "admin")) sessionStorage.setItem("notorganic-entry-view", requested);
    if ((requested === "integrations" || requested === "admin") || ["integrations","admin"].includes(sessionStorage.getItem("notorganic-entry-view") ?? "")) return requested === "admin" || sessionStorage.getItem("notorganic-entry-view") === "admin" ? "admin" : "integrations";
  } catch { /* Storage can be unavailable; direct links still work. */ }
  return requested === "admin" ? "admin" : requested === "integrations" ? "integrations" : "settings";
}
export function App() {
  const product = (document.documentElement.dataset.product ?? "notorganic") as Product;
  const [theme, setTheme] = useState<Theme>((document.documentElement.dataset.theme ?? "light") as Theme);
  const [session, setSession] = useState<SessionInfo | null>(null);
  const [checked, setChecked] = useState(false);
  const [view, setView] = useState<View>(initialView);

  const load = () => portalApi.session().then(setSession);

  useEffect(() => {
    void load().finally(() => setChecked(true));
  }, []);

  const signOut = async () => {
    await portalApi.logout();
    setSession(null);
    setView("settings");
  };

  return (
    <main className={!session ? "identity-shell" : undefined}>
      {!session && <IdentityLight product={product} />}
      <header className="masthead">
        <div className="page-title">
          <Wordmark />
          <button className="appearance-toggle" type="button" aria-label="Dark mode" role="switch" aria-checked={theme === "dark"} onClick={() => { const next = theme === "dark" ? "light" : "dark"; setTheme(next); applyAppearance({ product, theme: next }); }}>
            {theme === "dark" ? "Light appearance" : "Dark appearance"}
          </button>
          {!session && product !== "notorganic" && <div className="product-arrival"><img src={`/brand/${product}.png`} width="52" height="52" alt="" /><span>{PRODUCT_NAMES[product]} <small>Account by Not Organic</small></span></div>}
          <h1>{session ? "Your account" : `Your ${PRODUCT_NAMES[product]} account`}</h1>
        </div>
        {session && (
          <nav aria-label="Portal sections">
            {VIEWS.map((entry) => (
              <button
                key={entry.id}
                aria-pressed={view === entry.id}
                onClick={() => setView(entry.id)}
              >
                {entry.label}
              </button>
            ))}
            {session.isAdmin && <button onClick={() => setView("admin")} aria-pressed={view === "admin"}>
              Applications admin
            </button>}
            <button onClick={() => void signOut()}>Sign out</button>
          </nav>
        )}
      </header>

      <p className="lede">
        One account across Twyne, Keating, Interleave, and Stich. Your credits, activity, and
        privacy controls stay together.
      </p>

      {!checked ? (
        <p className="empty">Checking your session…</p>
      ) : !session ? (
        <SignIn onSignedIn={() => void load()} />
      ) : view === "integrations" ? (
        <IntegrationsView />
      ) : view === "settings" ? (
        <SettingsView />
      ) : view === "usage" ? (
        <UsageView />
      ) : view === "activity" ? (
        <ActivityView />
      ) : (
        <ApplicationAdmin allowed={session.isAdmin === true} />
      )}
    </main>
  );
}
import { useState } from "react";
import type {
  ProjectCiConfig,
  ProjectExecutionConfig,
  ProjectSourceConfig,
} from "@notorganic/contracts";
import { portalApi, type AccountView } from "../api";
import {
  Empty,
  Panel,
  planLabel,
  productLabel,
  StatusPill,
  timestamp,
  useLoader,
  useOperation,
} from "../ui";

function Identity({ account }: { account: AccountView }) {
  if (!account.account) {
    return <Empty>No provider account is linked to this DID yet.</Empty>;
  }
  const { did, handle, pdsUrl, recoveryState, createdAt } = account.account;
  return (
    <dl className="overview">
      <div>
        <dt>Handle</dt>
        <dd>{handle ?? "—"}</dd>
      </div>
      <div>
        <dt>DID</dt>
        <dd className="break">
          <code>{did}</code>
        </dd>
      </div>
      <div>
        <dt>PDS</dt>
        <dd className="break">{pdsUrl}</dd>
      </div>
      <div>
        <dt>Recovery</dt>
        <dd>
          <StatusPill status={recoveryState} />
        </dd>
      </div>
      <div>
        <dt>Member since</dt>
        <dd>{timestamp(createdAt)}</dd>
      </div>
    </dl>
  );
}

/**
 * Mirrors the one cross-field rule in `ProjectExecutionConfigSchema`, so the
 * reader sees why a combination is refused before the request is made. The
 * gateway remains the authority.
 */
function ciBlockedReason(source: ProjectSourceConfig, ci: ProjectCiConfig): string | null {
  if (ci.mode !== "disabled" && source.mode === "pds") {
    return "Spindle CI needs a Tangled repository. Choose a managed or external source first.";
  }
  return null;
}

function ProjectEditor({
  project,
  onSaved,
}: {
  project: ProjectExecutionConfig;
  onSaved: () => void;
}) {
  const [source, setSource] = useState<ProjectSourceConfig>(project.source);
  const [mirror, setMirror] = useState(project.source_mirror);
  const [ci, setCi] = useState<ProjectCiConfig>(project.ci);
  const [retention, setRetention] = useState(project.artifacts.retention_days);
  const save = useOperation();

  const blocked = ciBlockedReason(source, ci);
  const dirty =
    JSON.stringify({ source, mirror, ci, retention }) !==
    JSON.stringify({
      source: project.source,
      mirror: project.source_mirror,
      ci: project.ci,
      retention: project.artifacts.retention_days,
    });

  const submit = () =>
    void save.run(async () => {
      await portalApi.updateProject(project.project_id, {
        source,
        source_mirror: mirror,
        ci,
        artifacts: { provider: "r2", retention_days: retention },
      });
      onSaved();
    }, "Saved.");

  return (
    <li className="project">
      <div className="run-head">
        <strong>{project.project_id}</strong>
        <small className="hint">{productLabel(project.product)}</small>
      </div>

      <label>
        Source
        <select
