          "A+",
          "A",
          "A-",
          "B+",
          "B",
          "B-",
          "C+",
          "C",
          "C-",
          "D+",
          "D",
          "D-",
          "F",
        ].map((grade) => (
          <div
            key={`${grade}-${replay.value}`}
            class="flex flex-col items-center gap-4"
          >
            <GradeStamp
              grade={grade}
              score={grade === "A+" ? 98 : 80}
              color={
                grade.startsWith("A")
                  ? "#9c6c16"
                  : grade.startsWith("B")
                    ? "#207c73"
                    : "var(--color-vermilion)"
              }
              size="report"
              animated
            />
            <span>{grade}</span>
          </div>
        ))}
      </div>
      <div key={`workflow-${replay.value}`} class="mt-12 flex flex-wrap gap-8">
        <WorkflowStamp kind="filed" />
        <WorkflowStamp kind="revised" />
      </div>
    </div>
  );
});

