function ProfileSummary({ display }: { display: AccountDisplay }) {
  return (
    <div className="profile-summary">
      <AccountAvatar display={display} large />
      <div>
        <strong>{display.name}</strong>
        <span>{display.secondary}</span>
      </div>
    </div>
  );
}

function Identity({ account, session }: { account: AccountView; session: SessionInfo | null }) {
  const display = accountDisplayFromSources({ session, account });
  if (!account.account) {
    return (
      <>
        <ProfileSummary display={display} />
        {display.privateEmail && (
          <dl className="overview private-overview">
            <div>
              <dt>Private email</dt>
              <dd>{display.privateEmail}</dd>
            </div>
          </dl>
        )}
        <Empty>No provider account is linked to this DID yet.</Empty>
      </>
    );
  }
  const { did, handle, pdsUrl, recoveryState, createdAt } = account.account;
  return (
    <>
      <ProfileSummary display={display} />
      <dl className="overview">
        <div>
          <dt>Handle</dt>
          <dd>{handle ?? "—"}</dd>
        </div>
        {display.privateEmail && (
          <div>
            <dt>Private email</dt>
            <dd>{display.privateEmail}</dd>
          </div>
        )}
        <div>
          <dt>DID</dt>
          <dd className="break">
            <code>{did}</code>
          </dd>
        </div>
        <div>
          <dt>PDS</dt>
          <dd className="break">{pdsUrl}</dd>
        </div>
        <div>
          <dt>Recovery</dt>
          <dd>
            <StatusPill status={recoveryState} />
          </dd>
        </div>
        <div>
          <dt>Member since</dt>
          <dd>{timestamp(createdAt)}</dd>
        </div>
      </dl>
    </>
  );
}

/**
 * Mirrors the one cross-field rule in `ProjectExecutionConfigSchema`, so the
 * reader sees why a combination is refused before the request is made. The
 * gateway remains the authority.
 */
function ciBlockedReason(source: ProjectSourceConfig, ci: ProjectCiConfig): string | null {
  if (ci.mode !== "disabled" && source.mode === "pds") {
    return "Spindle CI needs a Tangled repository. Choose a managed or external source first.";
  }
  return null;
}

function ProjectEditor({
  project,
  onSaved,
}: {
  project: ProjectExecutionConfig;
  onSaved: () => void;
}) {
  const [source, setSource] = useState<ProjectSourceConfig>(project.source);
  const [mirror, setMirror] = useState(project.source_mirror);
  const [ci, setCi] = useState<ProjectCiConfig>(project.ci);
  const [retention, setRetention] = useState(project.artifacts.retention_days);
  const save = useOperation();

  const blocked = ciBlockedReason(source, ci);
  const dirty =
    JSON.stringify({ source, mirror, ci, retention }) !==
    JSON.stringify({
      source: project.source,
      mirror: project.source_mirror,
      ci: project.ci,
      retention: project.artifacts.retention_days,
    });

  const submit = () =>
    void save.run(async () => {
      await portalApi.updateProject(project.project_id, {
        source,
        source_mirror: mirror,
        ci,
        artifacts: { provider: "r2", retention_days: retention },
      });
      onSaved();
    }, "Saved.");

  return (
    <li className="project">
      <div className="run-head">
        <strong>{project.project_id}</strong>
        <small className="hint">{productLabel(project.product)}</small>
      </div>

      <label>
        Source
        <select
          value={source.mode}
          onChange={(event) => {
            const mode = event.target.value as ProjectSourceConfig["mode"];
            setSource(mode === "tangled_external" ? { mode, repo_uri: "" } : { mode });
          }}
        >
          <option value="pds">PDS only</option>
          <option value="tangled_managed">Notorganic-managed Tangled repository</option>
          <option value="tangled_external">My own Tangled repository</option>
        </select>
      </label>
      {source.mode === "tangled_external" && (
        <label>
          Repository AT-URI
          <input
            value={source.repo_uri}
            placeholder="at://did:plc:…/sh.tangled.repo/name"
            onChange={(event) => setSource({ mode: "tangled_external", repo_uri: event.target.value })}
          />
        </label>
      )}

      <label>
        Source mirroring
        <select value={mirror} onChange={(event) => setMirror(event.target.value as typeof mirror)}>
          <option value="disabled">Disabled</option>
          <option value="r2">Commit-pinned archive in R2</option>
        </select>
      </label>

      <label>
        CI trigger
        <select
          value={ci.mode}
          onChange={(event) => {
            const mode = event.target.value as ProjectCiConfig["mode"];
            if (mode === "spindle_managed") setCi({ mode, runner: "cloudflare_sandbox" });
            else if (mode === "spindle_external") setCi({ mode, spindle_uri: "" });
            else setCi({ mode: "disabled" });
          }}
        >
          <option value="disabled">Disabled</option>
          <option value="spindle_managed">Notorganic-managed Spindle</option>
          <option value="spindle_external">My own Spindle</option>
        </select>
      </label>
      {ci.mode === "spindle_managed" && (
        <label>
          Managed runner
          <select
            value={ci.runner}
            onChange={(event) =>
              setCi({ mode: "spindle_managed", runner: event.target.value as "cloudflare_sandbox" | "fly_sprite" })
            }
          >
            <option value="cloudflare_sandbox">Cloudflare Sandbox</option>
            <option value="fly_sprite">Disposable Fly Sprite</option>
          </select>
        </label>
      )}
      {ci.mode === "spindle_external" && (
        <label>
          Spindle AT-URI
          <input
            value={ci.spindle_uri}
            placeholder="at://did:plc:…/sh.tangled.spindle/name"
            onChange={(event) => setCi({ mode: "spindle_external", spindle_uri: event.target.value })}
          />
        </label>
      )}

      <label>
        Artifact retention (days)
        <input
          type="number"
          min={1}
          max={3650}
          value={retention}
          onChange={(event) => setRetention(Number(event.target.value))}
        />
      </label>

      {blocked && <p className="notice notice-bad">{blocked}</p>}
      <div className="button-row">
        <button disabled={!dirty || blocked !== null} onClick={submit}>
          Save changes
        </button>
      </div>
      <output>{save.message}</output>
    </li>
  );
}

export function SettingsView({ session }: { session: SessionInfo | null }) {
  const account = useLoader(() => portalApi.account(), []);
  const projects = useLoader(() => portalApi.projects(), []);

  return (
    <div className="grid">
      <Panel index={0} eyebrow="Identity" title="Your account">
        {account.error && <p className="notice notice-bad">{account.error}</p>}
        {account.loading && !account.data ? (
          <Empty>Loading…</Empty>
        ) : account.data ? (
          <Identity account={account.data} session={session} />
        ) : null}
      </Panel>

      <Panel index={1} eyebrow="Where you use it" title="Products and plans">
        {account.data && account.data.products.length === 0 && (
          <Empty>No products connected yet.</Empty>
        )}
        {account.data && account.data.products.length > 0 && (
          <>
            <p className="group-label">Products</p>
            <ul className="version-list">
              {account.data.products.map((product) => (
                <li key={product.product}>
                  <strong>{productLabel(product.product)}</strong>
                  <StatusPill status={product.status} />
                </li>
              ))}
            </ul>
          </>
        )}
        {account.data && account.data.subscriptions.length > 0 && (
          <>
            <p className="group-label">Plans you pay for</p>
            <ul className="version-list">
              {account.data.subscriptions.map((subscription) => (
                <li key={`${subscription.plan}-${subscription.status}`}>
                  <strong>{planLabel(subscription.plan)}</strong>
                  <StatusPill status={subscription.status} />
                  {subscription.currentPeriodEnd && (
                    <small className="hint">
                      Renews {timestamp(subscription.currentPeriodEnd)}
                    </small>
                  )}
                </li>
              ))}
            </ul>
          </>
        )}
        <p className="hint">
          Top-ups and plan changes happen in the product you bought them from. Your wallet is shared
          across all of them.
        </p>
      </Panel>

      <Panel index={2} eyebrow="Execution" title="Project configuration" wide>
        {projects.error && <p className="notice notice-bad">{projects.error}</p>}
        {projects.loading && !projects.data ? (
          <Empty>Loading…</Empty>
        ) : (projects.data ?? []).length === 0 ? (
          <Empty>
            No projects configured yet. A project appears here once a product creates one for you.
          </Empty>
        ) : (
          <ul className="project-list">
            {(projects.data ?? []).map((project) => (
              <ProjectEditor
                key={`${project.product}-${project.project_id}`}
                project={project}
                onSaved={() => void projects.refresh()}
              />
            ))}
          </ul>
        )}
        <p className="hint">
          Managed Tangled hosting is a collaboration home, not an artifact store. Build artifacts
          always land in Notorganic-managed R2 with the retention set here.
        </p>
      </Panel>
    </div>
  );
}
import { useEffect, useState } from "react";
import type { AccountDisplay } from "./account-display";

type AvatarDisplay = Pick<AccountDisplay, "name" | "initials" | "avatarUrl">;

export function shouldRenderAvatarImage(src: string | null, failedSrc: string | null): src is string {
  return src !== null && src !== failedSrc;
}

export function AccountAvatar({
  display,
  large = false,
}: {
  display: AvatarDisplay;
  large?: boolean;
}) {
  const [failedSrc, setFailedSrc] = useState<string | null>(null);
  const src = display.avatarUrl;

  useEffect(() => {
    setFailedSrc(null);
  }, [src]);

  const showImage = shouldRenderAvatarImage(src, failedSrc);
  const className = large ? "account-avatar account-avatar-large" : "account-avatar";

  return (
    <span className={className} aria-label={`Account avatar for ${display.name}`} role="img">
      {showImage ? (
        <img
          key={src}
          src={src}
          alt=""
          decoding="async"
          referrerPolicy="no-referrer"
          onError={() => setFailedSrc(src)}
        />
      ) : (
        <span>{display.initials}</span>
      )}
    </span>
  );
}
import type { SessionInfo, AccountView } from "./api";

/** Optional authenticated profile projection supplied by the session worker. */
export type SessionInfoWithProfile = SessionInfo & {
  profile?: {
    displayName?: string | null;
    handle?: string | null;
    avatarUrl?: string | null;
    email?: string | null;
  } | null;
};

export interface AccountDisplay {
  name: string;
  secondary: string;
  initials: string;
  avatarUrl: string | null;
  privateEmail: string | null;
}

export function accountDisplayForSession(session: SessionInfoWithProfile | null): AccountDisplay {
  return accountDisplayFromSources({ session });
}

export function accountDisplayFromSources({
  session,
  account,
}: {
  session: SessionInfoWithProfile | null;
  account?: AccountView | null;
}): AccountDisplay {
  const profile = session?.profile ?? null;
  const privateEmail = normalizeEmail(profile?.email);
  const handle = normalizeHandle(profile?.handle) ?? normalizeHandle(account?.account?.handle);
  const displayName = normalizeDisplayName(profile?.displayName, privateEmail);
  const did = session?.did ?? account?.account?.did ?? null;
  const name = displayName ?? handle ?? "Signed-in account";
  const secondary = handle && handle !== name ? handle : shortenDid(did) ?? "Not Organic";

  return {
    name,
    secondary,
    initials: initialsFor(displayName ?? handle ?? did),
    avatarUrl: safeAvatarUrl(profile?.avatarUrl),
    privateEmail,
  };
}

function normalizeDisplayName(value: unknown, email: string | null): string | null {
  const text = normalizeText(value);
  if (!text) return null;
  if (email && text.toLowerCase() === email.toLowerCase()) return null;
  if (looksLikeEmail(text)) return null;
  return text;
}

function normalizeHandle(value: unknown): string | null {
  const text = normalizeText(value)?.replace(/^@+/, "");
  if (!text || looksLikeEmail(text)) return null;
  return text;
}

function normalizeEmail(value: unknown): string | null {
  const text = normalizeText(value);
  if (!text) return null;
  const match = text.match(EMAIL_PATTERN);
  return match?.[0] ?? null;
}

function normalizeText(value: unknown): string | null {
  return typeof value === "string" && value.trim() ? value.trim() : null;
}

function safeAvatarUrl(value: unknown): string | null {
  const text = normalizeText(value);
  if (!text) return null;
  if (text.includes("\\") || text.startsWith("//")) return null;
  if (text.startsWith("/") && !text.startsWith("//")) return text;
  try {
    const url = new URL(text);
    if (url.username || url.password) return null;
    return url.protocol === "https:" ? url.toString() : null;
  } catch {
    return null;
  }
}

const EMAIL_PATTERN = /[^\s<>()@]+@[^\s<>()@]+/i;

function looksLikeEmail(value: string): boolean {
  return EMAIL_PATTERN.test(value);
}

function initialsFor(value: string | null | undefined): string {
  const text = normalizeText(value);
  if (!text) return "NO";
  const words = text
    .replace(/^did:\w+:/, "")
    .split(/[\s._-]+/)
    .filter(Boolean);
  const first = words[0] ?? text;
  const second = words.find((word) => word !== first);
  return [first, second]
    .filter(Boolean)
    .map((word) => Array.from(word ?? "")[0]?.toUpperCase() ?? "")
    .join("")
    .slice(0, 2) || "NO";
}

function shortenDid(value: string | null | undefined): string | null {
  const text = normalizeText(value);
  if (!text) return null;
  if (text.length <= 24) return text;
  return `${text.slice(0, 13)}...${text.slice(-6)}`;
}

