  --forest-deep: #082718;
  --leaf: #b9db43;
  --leaf-light: #e5f0a8;
  --water: #4d7c67;
  --petal: #e7a0b4;
  --sun: #f2c879;
  --dusk: #a9b6e0;
  --ink: #102519;
  --ink-soft: #3f5849;
  --ink-muted: #63796b;
  --off-white: #f7f8f0;

