import { expect, test } from "bun:test";
import {
  accountDisplayForSession,
  accountDisplayFromSources,
  type SessionInfoWithProfile,
} from "./account-display";

const baseSession: SessionInfoWithProfile = {
  authenticated: true,
  csrfToken: "csrf",
  did: "did:plc:REDACTED",
  expiresAt: 1,
};

test("uses authenticated profile name, handle and avatar when present", () => {
  const display = accountDisplayForSession({
    ...baseSession,
    profile: {
      displayName: "Ada Lovelace",
      handle: "ada.notorganic.info",
      avatarUrl: "https://cdn.notorganic.info/ada.webp",
    },
  });

  expect(display.name).toBe("Ada Lovelace");
  expect(display.secondary).toBe("ada.notorganic.info");
  expect(display.initials).toBe("AL");
  expect(display.avatarUrl).toBe("https://cdn.notorganic.info/ada.webp");
  expect(display.privateEmail).toBeNull();
});

test("never turns email into the public display name", () => {
  const display = accountDisplayForSession({
    ...baseSession,
    profile: {
      displayName: "person@example.com",
      email: "person@example.com",
    },
  });

  expect(display.name).toBe("Signed-in account");
  expect(display.secondary).toBe("did:plc:abcde...456789");
  expect(display.privateEmail).toBe("person@example.com");
});

test("never leaks embedded private email from public profile fields", () => {
  const display = accountDisplayForSession({
    ...baseSession,
    profile: {
      displayName: "Morgan <private@example.test>",
      handle: "morgan private@example.test",
      email: "private@example.test",
    },
  });

  expect(display.name).toBe("Signed-in account");
  expect(display.secondary).toBe("did:plc:abcde...456789");
  expect(display.initials).not.toContain("M");
  expect(display.name).not.toContain("private@example.test");
  expect(display.secondary).not.toContain("private@example.test");
  expect(display.privateEmail).toBe("private@example.test");
});

test("also rejects email labels without a dotted domain", () => {
  const display = accountDisplayForSession({
    ...baseSession,
    profile: { displayName: "person@localhost", handle: "person@localhost" },
  });
  expect(display.name).toBe("Signed-in account");
  expect(display.secondary).not.toContain("person@localhost");
});

test("keeps private email separate and uses handle fallback", () => {
  const display = accountDisplayForSession({
    ...baseSession,
    profile: {
      handle: "@reader.notorganic.info",
      email: "reader@example.com",
    },
  });

  expect(display.name).toBe("reader.notorganic.info");
  expect(display.secondary).toBe("did:plc:abcde...456789");
  expect(display.privateEmail).toBe("reader@example.com");
});

test("falls back to authenticated account handle without external lookup", () => {
  const display = accountDisplayFromSources({
    session: baseSession,
    account: {
      account: {
        did: baseSession.did,
        handle: "account.notorganic.info",
        pdsUrl: "https://pds.notorganic.info",
        recoveryState: "active",
        createdAt: 1,
      },
      products: [],
      subscriptions: [],
    },
  });

  expect(display.name).toBe("account.notorganic.info");
  expect(display.secondary).toBe("did:plc:abcde...456789");
});

test("rejects unsafe avatar URLs", () => {
  for (const avatarUrl of [
    "javascript:alert(1)",
    "http://cdn.notorganic.info/ada.webp",
    "//cdn.notorganic.info/ada.webp",
    "\\avatars\\ada.webp",
    "/\\avatars/ada.webp",
    "REDACTED",
  ]) {
    const display = accountDisplayForSession({
      ...baseSession,
      profile: {
        displayName: "Ada",
        avatarUrl,
      },
    });

    expect(display.avatarUrl).toBeNull();
  }
});

test("accepts https and same-origin avatar image paths", () => {
  const remote = accountDisplayForSession({
    ...baseSession,
    profile: {
      displayName: "Ada",
      avatarUrl: "https://cdn.notorganic.info/ada.webp",
    },
  });
  const local = accountDisplayForSession({
    ...baseSession,
    profile: {
      displayName: "Ada",
      avatarUrl: "/avatars/ada.webp?size=64",
    },
  });

  expect(remote.avatarUrl).toBe("https://cdn.notorganic.info/ada.webp");
  expect(local.avatarUrl).toBe("/avatars/ada.webp?size=64");
});
