import { useState } from "react";

/** Keep the private value out of the page until the account holder reveals it. */
export function PrivateEmail({ email }: { email: string }) {
  const [revealed, setRevealed] = useState(false);

  return (
    <details
      className="private-email"
      onToggle={(event) => setRevealed(event.currentTarget.open)}
    >
      <summary>Private email</summary>
      {revealed && <p className="private-email-value">{email}</p>}
    </details>
  );
}

import { expect, test } from "bun:test";
import { renderToStaticMarkup } from "react-dom/server";
import { PrivateEmail } from "./private-email";

test("private email is absent from the default disclosure markup and accessibility metadata", () => {
