import { chromium, expect } from "/home/diogenes/Projects/twyne/node_modules/@playwright/test/index.mjs";
import { mkdir, readFile, writeFile } from "node:fs/promises";

const directory = process.env.PORTAL_QA_DIR ?? "/home/diogenes/Projects/notorganic-provider/tmp/qa-recordings/2026-09-30/portal-account-privacy";
const baseUrl = process.env.PORTAL_QA_URL ?? "http://127.0.0.1:5179/";
await mkdir(directory, { recursive: true });
const avatar = await readFile("/home/diogenes/Projects/twyne/public/assets/avatars/engraved-2026-09/owl.webp");
const email = "morgan.private@example.test";
const did = "did:plc:syntheticmorganvale";
let profile = { displayName: "Morgan Vale", handle: "morgan.notorganic.test", avatarUrl: "/synthetic-avatar.webp", email };
let linkedAccount = true;
const sessions = [];
const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({
  viewport: { width: 1440, height: 900 },
  recordVideo: { dir: directory, size: { width: 1440, height: 900 } },
});
const page = await context.newPage();
const errors = [];
page.on("pageerror", (error) => errors.push(error.message));
await page.route("**/*", async (route) => {
  const url = new URL(route.request().url());
  if (url.hostname !== "127.0.0.1" && url.hostname !== "localhost") return route.abort();
  const json = (payload) => route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(payload) });
  if (url.pathname === "/api/session") {
    const session = { authenticated: true, csrfToken: "synthetic-csrf", did, expiresAt: 4102444800000, profile: { ...profile } };
    sessions.push(session);
    return json(session);
  }
  if (url.pathname === "/api/account") return json({
    account: linkedAccount ? { did, handle: "morgan.notorganic.test", pdsUrl: "https://pds.notorganic.test", recoveryState: "active", createdAt: 1790726400000 } : null,
    products: [], subscriptions: [],
  });
  if (url.pathname === "/api/projects") return json({ object: "list", data: [] });
  if (url.pathname === "/api/integrations") return json([]);
  if (url.pathname === "/synthetic-avatar.webp" || url.pathname === "/synthetic-avatar-updated.webp") return route.fulfill({ status: 200, contentType: "image/webp", body: avatar });
  if (url.pathname === "/synthetic-missing-avatar.webp") return route.fulfill({ status: 404, contentType: "image/webp", body: "" });
  if (url.pathname.startsWith("/api/")) return route.abort();
  return route.continue();
});

async function assertMetadataPrivate() {
  const metadata = await page.locator("body").evaluate((body) =>
    Array.from(body.querySelectorAll("*")).flatMap((element) =>
      Array.from(element.attributes)
        .filter((attribute) => attribute.name === "title" || attribute.name === "alt" || attribute.name.startsWith("aria-") || attribute.name.includes("tooltip"))
        .map((attribute) => attribute.value),
    ).join("\n"),
  );
  expect(metadata).not.toContain(email);
}

async function assertClosedPrivate() {
  await expect(page.locator(".private-email")).not.toHaveAttribute("open", "");
  await expect(page.getByText(email, { exact: true })).toHaveCount(0);
  expect(await page.locator("body").innerText()).not.toContain(email);
  expect(await page.locator("body").innerText()).not.toContain("@");
  expect(await page.locator("body").evaluate((body) => body.outerHTML)).not.toContain(email);
  expect(await page.locator("body").ariaSnapshot()).not.toContain(email);
  await assertMetadataPrivate();
}

async function refreshSession() {
  const count = sessions.length;
  await page.evaluate(() => window.dispatchEvent(new Event("focus")));
  await expect.poll(() => sessions.length).toBeGreaterThan(count);
}

let outcome;
try {
  await page.goto(baseUrl, { waitUntil: "domcontentloaded" });
  await expect(page.getByRole("heading", { name: "Morgan Vale", exact: true })).toBeVisible();
  await expect(page.getByRole("button", { name: "Settings", exact: true })).toHaveAttribute("aria-pressed", "true");
  await expect(page.locator(".profile-summary")).toContainText("Morgan Vale");
  await expect(page.locator(".account-avatar img")).toHaveCount(2);
  await expect.poll(() => page.locator(".account-avatar img").evaluateAll((images) => images.every((image) => image.complete && image.naturalWidth > 0))).toBe(true);
  expect(sessions[0].profile.email).toBe(email);
  await assertClosedPrivate();
  await page.screenshot({ path: `${directory}/default-settings-private.png` });

  profile = { ...profile, displayName: "M. Vale", avatarUrl: null };
  await refreshSession();
  await expect(page.getByRole("heading", { name: "M. Vale", exact: true })).toBeVisible();
  await expect(page.locator(".profile-summary")).toContainText("M. Vale");
  await expect(page.locator(".account-avatar img")).toHaveCount(0);
  await expect(page.locator(".account-avatar").first()).toContainText("MV");
  await assertClosedPrivate();
  await page.screenshot({ path: `${directory}/returned-settings-private.png` });

  profile = { ...profile, avatarUrl: "/synthetic-missing-avatar.webp" };
  const failedImage = page.waitForResponse((response) => response.url().endsWith("/synthetic-missing-avatar.webp") && response.status() === 404);
  await refreshSession();
  await failedImage;
  await expect(page.locator(".account-avatar img")).toHaveCount(0);
  await assertClosedPrivate();

  profile = { ...profile, avatarUrl: "/synthetic-avatar-updated.webp" };
  await refreshSession();
  await expect(page.locator(".account-avatar img")).toHaveCount(2);
  await expect.poll(() => page.locator(".account-avatar img").evaluateAll((images) => images.every((image) => image.complete && image.naturalWidth > 0))).toBe(true);
  await assertClosedPrivate();

  const summary = page.locator(".private-email summary");
  await summary.focus();
  await page.keyboard.press("Enter");
  await expect(page.locator(".private-email")).toHaveAttribute("open", "");
  await expect(page.locator(".private-email-value")).toHaveText(email);
  await expect(page.getByText(email, { exact: true })).toBeVisible();
  await assertMetadataPrivate();
  expect(await page.locator(".masthead").innerText()).not.toContain(email);
  await page.screenshot({ path: `${directory}/deliberate-private-email-reveal.png` });
  await page.keyboard.press("Enter");
  await assertClosedPrivate();

  await summary.click();
  await expect(page.getByText(email, { exact: true })).toBeVisible();
  await page.getByRole("button", { name: "Your apps", exact: true }).click();
  await expect(page.locator(".private-email")).toHaveCount(0);
  await page.getByRole("button", { name: "Settings", exact: true }).click();
  await expect(page.locator(".private-email summary")).toBeVisible();
  await assertClosedPrivate();

  linkedAccount = false;
  await page.reload({ waitUntil: "domcontentloaded" });
  await expect(page.getByText("No provider account is linked to this DID yet.", { exact: true })).toBeVisible();
  await assertClosedPrivate();
  await page.screenshot({ path: `${directory}/unlinked-account-private.png` });
  await page.locator(".private-email summary").click();
  await expect(page.getByText(email, { exact: true })).toBeVisible();
  await page.locator(".private-email summary").click();
  await assertClosedPrivate();

  const { email: omitted, ...publicProfile } = profile;
  profile = publicProfile;
  await refreshSession();
  await expect(page.locator(".private-email")).toHaveCount(0);
  expect(await page.locator("body").innerText()).not.toContain(email);
  await assertMetadataPrivate();
  expect(errors).toEqual([]);
  outcome = {
    passed: true,
    proof: "Actual portal UI with synthetic network responses; no live authenticated exchange",
    viewport: { width: 1440, height: 900 },
    syntheticAccount: { name: "Morgan Vale", handle: "morgan.notorganic.test", privateEmail: email },
    syntheticEmailPresentInSession: sessions.slice(0, -1).every((session) => session.profile.email === email),
    initialView: "settings (default URL, fresh browser context)",
    assertions: [
      "Default Settings hides email from visible text, DOM, tooltip/ARIA attributes and accessibility snapshot",
      "Return-to-tab refresh preserves privacy while refreshing name and loaded/absent/broken/replaced avatar",
      "Keyboard Enter deliberately reveals email inside private disclosure; Enter closes and removes it from DOM",
      "Click reveal followed by navigation back to Settings resets to closed",
      "No linked provider account still defaults closed and supports deliberate reveal/close",
      "Public-only session profile omits disclosure",
      "No page errors",
    ],
    pageErrors: errors,
  };
} catch (error) {
  await page.screenshot({ path: `${directory}/failure.png` });
  outcome = { passed: false, error: String(error), pageErrors: errors, body: (await page.locator("body").innerText()).slice(0, 4000) };
  process.exitCode = 1;
} finally {
  const video = page.video();
  await context.close();
  outcome.video = await video.path();
  await browser.close();
  await writeFile(`${directory}/result.json`, JSON.stringify(outcome, null, 2));
  console.log(JSON.stringify(outcome, null, 2));
}

