.grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
}

.panel {
  min-width: 0;
  padding: 24px;
  background: var(--panel);
  background-image: var(--tex-hatch);
  background-blend-mode: multiply;
  border: 1px solid var(--line);
  border-radius: var(--radius);
}
.panel-wide { grid-column: 1 / -1; }
.panel p { color: var(--ink-soft); line-height: 1.58; }

/* Panels arrive staggered on first paint. juice.ts sets the
   index; a view with two panels resolves in under 200ms, which
   is short enough to read as the page assembling rather than as
   the page being slow. */
.panel[data-reveal] {
  opacity: 0;
  transform: translate3d(0, 14px, 0);
  transition:
    opacity 520ms var(--ease-settle),
    transform 520ms var(--ease-overshoot);
  transition-delay: calc(var(--reveal-index, 0) * 55ms);
}
.panel[data-reveal].is-revealed { opacity: 1; transform: none; }

/* --- Forms --------------------------------------------------- */
form, .delete-row { display: grid; gap: 14px; }

label {
  display: grid;
  gap: 6px;
  font-size: 0.8rem;

